package com.phantom.tube.ui.components

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.unit.dp

/**
 * Compact local vector icon registry replacing material-icons-extended.
 * Standard core icons remain in material-icons-core; non-core icons are
 * lazily parsed once from compact SVG path strings into cached ImageVectors.
 */
object PhantomIcons {
    private val cache = arrayOfNulls<ImageVector>(61)

    private fun icon(
        index: Int,
        name: String,
        pathData: String,
        autoMirror: Boolean = false
    ): ImageVector {
        cache[index]?.let { return it }
        return synchronized(cache) {
            cache[index] ?: buildIcon(name, pathData, autoMirror).also { cache[index] = it }
        }
    }

    private fun buildIcon(name: String, pathData: String, autoMirror: Boolean): ImageVector {
        val builder = ImageVector.Builder(
            name = name,
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = 24f,
            viewportHeight = 24f,
            autoMirror = autoMirror
        )
        val fill = SolidColor(Color.Black)
        pathData.split('|').forEach { segment ->
            builder.addPath(pathData = addPathNodes(segment), fill = fill)
        }
        return builder.build()
    }

